CREATE OR REPLACE FUNCTION public.is_admin_for_member_data(check_user_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  co TEXT;
BEGIN
  co := get_current_org_id();
  IF is_current_super_admin() THEN RETURN TRUE; END IF;
  IF is_current_admin() AND co IS NOT NULL THEN
    -- When called from users_select_admin policy under FORCE RLS,
    -- querying users here would recurse infinitely.
    -- For users table, the caller should use is_admin_for_org(organization_id)
    -- directly. For other tables, the users lookup is safe.
    RETURN EXISTS (
      SELECT 1 FROM users u
      WHERE u.id = check_user_id AND u.organization_id = co
    );
  END IF;
  RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_counselor_for_member(check_member_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE cu TEXT;
BEGIN
  IF get_current_role() = 'system' THEN RETURN TRUE; END IF;
  cu := get_current_user_id();
  IF cu IS NULL THEN RETURN FALSE; END IF;
  RETURN EXISTS (SELECT 1 FROM counselor_assignments ca JOIN counselors c ON ca.counselor_id = c.id WHERE ca.member_id = check_member_id AND c.user_id = cu AND ca.active = true);
END;
$function$

CREATE OR REPLACE FUNCTION public.is_current_employer(check_employer_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE cu TEXT;
BEGIN
  IF get_current_role() = 'system' THEN RETURN TRUE; END IF;
  cu := get_current_user_id();
  IF cu IS NULL THEN RETURN FALSE; END IF;
  RETURN EXISTS (SELECT 1 FROM employers e WHERE e.id = check_employer_id AND e.user_id = cu);
